<script setup>
import { onMounted, reactive, ref } from 'vue';
import { useRouter } from 'vue-router';
import axios from 'axios';
import AppIcon from '../components/base/AppIcon.vue';
import TemporaryLinkCard from '../components/gamekit/TemporaryLinkCard.vue';

const router = useRouter(); const games = ref([]), words = ref([]), editingId = ref(null), loading = ref(false), aiLoading = ref(false), message = ref(''), error = ref(''), link = ref('');
const form = reactive({ name: 'Forca divertida', age_group: 'Criança', theme: 'Animais', word_count: 6 });
const load = async () => { try { games.value = (await axios.get('/api/gamekit/hangman/games')).data.games ?? []; } catch { /* opcional */ } }; const generate = async () => { aiLoading.value = true; error.value = ''; try { words.value = (await axios.post('/api/gamekit/hangman/ai-generate', { age_group: form.age_group, theme: form.theme, word_count: form.word_count })).data.words ?? []; message.value = 'Palavras geradas. Revise antes de salvar.'; } catch (e) { error.value = e?.response?.data?.message ?? 'Não foi possível gerar as palavras.'; } finally { aiLoading.value = false; } }; const save = async () => { if (words.value.length < 4) { error.value = 'Gere ou adicione pelo menos quatro palavras.'; return; } loading.value = true; try { const payload = { ...form, words: words.value }; const data = (editingId.value ? await axios.put('/api/gamekit/hangman/games/' + editingId.value, payload) : await axios.post('/api/gamekit/hangman/games', payload)).data; games.value = editingId.value ? games.value.map(item => item.id === data.id ? data : item) : [data, ...games.value]; message.value = editingId.value ? 'Modelo atualizado.' : 'Modelo salvo.'; editingId.value = null; } catch (e) { error.value = e?.response?.data?.message ?? 'Não foi possível salvar o modelo.'; } finally { loading.value = false; } }; const edit = (game) => { editingId.value = game.id; Object.assign(form, { name: game.name, age_group: game.age_group, theme: game.theme, word_count: game.word_count }); words.value = [...(game.words ?? [])]; }; const remove = async (game) => { if (!window.confirm('Excluir este modelo?')) return; await axios.delete('/api/gamekit/hangman/games/' + game.id); games.value = games.value.filter(item => item.id !== game.id); }; const start = async (game) => { try { const session = (await axios.post('/api/gamekit/hangman/games/' + game.id + '/sessions')).data; link.value = (await axios.post('/api/gamekit/hangman/sessions/' + session.id + '/link')).data.url; await navigator.clipboard?.writeText(link.value); message.value = 'Link copiado.'; } catch (e) { error.value = e?.response?.data?.message ?? 'Não foi possível criar a sessão.'; } }; onMounted(load);
</script>
<template><main class="page-shell space-y-6"><header class="page-header"><div class="page-header__content"><button class="btn-secondary mb-4" type="button" @click="router.push('/gamekit')"><AppIcon name="ArrowLeft" class="size-4" />Voltar para o GameKit</button><p class="section-kicker">GameKit Psi · Jogo da Forca</p><h1 class="page-header__title">Forca divertida</h1><p class="page-header__description">Escolha um tema, deixe a IA sugerir palavras e revise tudo antes de jogar.</p></div></header><p v-if="message" class="rounded-2xl border border-[#c9d8cd] bg-[#edf4ef] px-4 py-3 text-sm text-[#365341]">{{ message }}</p><p v-if="error" class="rounded-2xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">{{ error }}</p><section class="grid gap-6 xl:grid-cols-[minmax(0,1fr)_360px]"><div class="surface-panel p-5 sm:p-6"><div class="flex items-start gap-3"><span class="flex size-11 items-center justify-center rounded-2xl bg-[var(--spa-accent-soft)] text-[var(--spa-accent)]"><AppIcon name="Languages" class="size-5" /></span><div><p class="section-kicker">Novo modelo</p><h2 class="text-lg font-semibold text-[var(--spa-ink)]">Palavras para a sessão</h2></div></div><div class="mt-5 grid gap-4 md:grid-cols-2"><label class="field-label">Nome<input v-model="form.name" class="field-input mt-1" /></label><label class="field-label">Faixa etária<select v-model="form.age_group" class="field-input mt-1"><option>Criança</option><option>Adolescente</option><option>Adulto</option></select></label><label class="field-label">Tema<input v-model="form.theme" class="field-input mt-1" placeholder="Ex.: animais" /></label><label class="field-label">Quantidade<select v-model.number="form.word_count" class="field-input mt-1"><option :value="4">4 palavras</option><option :value="6">6 palavras</option><option :value="8">8 palavras</option><option :value="10">10 palavras</option><option :value="12">12 palavras</option></select></label></div><div class="mt-5 flex flex-wrap gap-2"><button class="btn-primary" type="button" :disabled="aiLoading" @click="generate"><AppIcon name="Sparkles" class="size-4" />{{ aiLoading ? 'Gerando...' : 'Gerar com IA' }}</button><button class="btn-secondary" type="button" @click="words.push('Nova palavra')"><AppIcon name="Plus" class="size-4" />Adicionar palavra</button></div><div class="mt-6 grid gap-2 sm:grid-cols-2"><label v-for="(_, index) in words" :key="index" class="field-label">Palavra {{ index + 1 }}<div class="flex gap-2"><input v-model="words[index]" class="field-input mt-1" /><button class="mt-1 inline-flex size-10 shrink-0 items-center justify-center rounded-xl text-red-600 hover:bg-red-50" type="button" aria-label="Excluir palavra" @click="words.splice(index, 1)"><AppIcon name="Trash2" class="size-4" /></button></div></label></div><div class="mt-6 flex justify-end border-t border-[var(--spa-border)] pt-5"><button class="btn-primary" type="button" :disabled="loading" @click="save">{{ loading ? 'Salvando...' : (editingId ? 'Atualizar modelo' : 'Salvar modelo') }}</button></div></div><aside class="surface-panel p-5"><p class="section-kicker">Modelos salvos</p><div v-if="games.length" class="mt-4 space-y-3"><article v-for="game in games" :key="game.id" class="rounded-2xl border border-[var(--spa-border)] bg-white p-4"><div class="flex items-start justify-between gap-2"><div><h3 class="font-semibold text-[var(--spa-ink)]">{{ game.name }}</h3><p class="mt-1 text-xs text-[var(--spa-ink-muted)]">{{ game.theme }} · {{ game.words?.length ?? 0 }} palavras</p></div><button class="text-red-600" type="button" aria-label="Excluir modelo" @click="remove(game)"><AppIcon name="Trash2" class="size-4" /></button></div><div class="mt-3 flex gap-2"><button class="btn-secondary" type="button" @click="edit(game)">Editar</button><button class="btn-primary" type="button" @click="start(game)">Usar em sessão</button></div></article></div><p v-else class="mt-4 text-sm text-[var(--spa-ink-muted)]">Nenhum modelo salvo.</p><TemporaryLinkCard v-if="link" class="mt-5" :url="link" label="Link da forca" /></aside></section></main></template>
